def is_frame(grid, color, r, c):
    """Check if this color forms a hollow rectangle frame"""
    # Find bounding box
    cells = []
    for rr in range(len(grid)):
        for cc in range(len(grid[0])):
            if grid[rr][cc] == color:
                cells.append((rr, cc))

    if len(cells) < 4:
        return None

    min_r, min_c = min(cells, key=lambda x: (x[0], x[1]))
    max_r, max_c = max(cells, key=lambda x: (x[0], x[1]))

    height = max_r - min_r + 1
    width = max_c - min_c + 1

    # Check if all edge cells are this color
    frame = True
    for rr in range(min_r, max_r + 1):
        if grid[rr][min_c] != color or grid[rr][max_c] != color:
            frame = False
            break
    for cc in range(min_c, max_c + 1):
        if grid[min_r][cc] != color or grid[max_r][cc] != color:
            frame = False
            break

    if frame and height >= 3 and width >= 3:
        interior = []
        for rr in range(min_r + 1, max_r):
            for cc in range(min_c + 1, max_c):
                interior.append((rr, cc))
        return {
            'color': color,
            'min_r': min_r, 'max_r': max_r,
            'min_c': min_c, 'max_c': max_c,
            'height': height, 'width': width,
            'max_dim': max(height, width),
            'interior': interior
        }
    return None

