def find_direct_frames(grid):
    """Find rectangular frames with uniform border"""
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == BG:
                continue
            # Try to find a frame rectangle starting at (r,c)
            for H in range(2, min(h-r+1, w-c+1)):
                for W in range(2, min(h-r+1, w-c+1)):
                    r2, c2 = r+H-1, c+W-1
                    # Check if valid frame (border is uniform, interior is BG)
                    border_ok = True
                    for i in range(H):
                        if grid[r][c+i] != color:
                            border_ok = False
                        if grid[r2][c+i] != color:
                            border_ok = False
                    for j in range(1, W-1):
                        if grid[r][c+j] != color:
                            border_ok = False
                        if grid[r2][c+j] != color:
                            border_ok = False
                    for i in range(1, H-1):
                        if grid[r+i][c] != color:
                            border_ok = False
                        if grid[r+i][c2] != color:
                            border_ok = False

                    if not border_ok:
                        continue

                    # Check interior is BG
                    interior_ok = True
                    for i in range(1, H):
                        for j in range(1, W):
