def detect_all_frames(grid):
    """Detect all hollow rectangular frames in the grid. Returns list of (color, top, left, bottom, right)"""
    frames = []

    # Horizontal scan
    for r in range(h):
        for c1 in range(w):
            for c2 in range(c1+2, w+1):
                # Check if this horizontal segment could be top or bottom border
                if r == h-1 and grid[r][c1:c2+1] == [6] * (c2-c1+1):
                    continue  # Skip
                if grid[r][c1] == grid[r][c2] and c2-c1 >= 2:
                    for r2 in range(r+1, h):
                        # Check if we've found a closing border
                        if r2 == r+2 and c2-c1 <= 4 and grid[r2][c1] == grid[r][c1]:
                            # Check bottom border
                            if grid[r2][c1:c2+1] == grid[r][c1:c2+1]:
                                # Check if interior is uniform
                                inner_color = grid[r+1][c1+1]
                                inner_ok = True
                                for rr in range(r+1, r2):
                                    for cc in range(c1+1, c2):
                                        if grid[rr][cc] != inner_color:
                                            inner_ok = False
                                            break
                                    if not inner_ok:
                                        break
                                if inner_ok:
                                    # Check if this color is uniform for non-interior border cells
                                    border_color = grid[r][c1]
                                    border_ok = True
                                    for rr in range(r, r2+1):
                                        for cc in range(c1, c2+1):
                                            if (rr == r or rr == r2 or cc == c1 or cc == c2):
                                                if grid[rr][cc] != border_color:
                                                    border_ok = False
                                                    break
                                        if not border_ok:
                                            break
                                    if border_ok:
                                        frames.append((border_color, r, c1, r2, c2))
                                break
    return frames

